{
  "interpretation": {
    "name": "TightenF25AtStation1WithNR7",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Bring NR7 from the crib to station st1, tighten the fasteners of the incoming F25 per its MES program, evaluate and record the result, then return NR7 to the crib and release the reservation.",
    "constraints": [
      "NR7 must be reserved before any use, and every tool-using Step renews the lease with the reservation token",
      "transport-tool is delegated to the Executor agvexecutor",
      "NR7 must be at st1 before configure-tool and tighten-fasteners",
      "The tightening program (bolt count, torque, tolerance) comes only from get-program, with no literals in the Recipe",
      "The tightening must be evaluated and recorded for traceability",
      "NR7 must be returned to the crib and the reservation released so that other requesters are not blocked"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "One-off job for the upcoming F25 at station st1 on line 1",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "f25-tightening-st1-nr7",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "reserve-nr7",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-f25-program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-nr7-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "quality",
        "steps": [
          {
            "name": "configure-nr7",
            "service": "configure-tool",
            "next": ["tighten-nr7"],
            "dep": ["get-f25-program", "reserve-nr7", "transport-nr7-to-station"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-nr7",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure-nr7", "reserve-nr7", "transport-nr7-to-station"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "quality",
        "next": "return-and-release",
        "steps": [
          {
            "name": "evaluate-f25-tightening",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-nr7", "get-f25-program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-f25-tightening",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-and-release",
        "next": null,
        "steps": [
          {
            "name": "transport-nr7-to-crib",
            "service": "transport-tool",
            "next": ["release-nr7"],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-nr7",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-nr7", "transport-nr7-to-crib"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
